			    var sipb6 = e.control;
			    util.Dialog.open(app, "app/itgcm/bizcmmns/popup/trprInfoInqPop", "사례대상자 정보 조회", 1280, 600, function(e) {
			        
			        var dialog = e.control;
			        /**
			         * @type cpr.data.RowConfigInfo
			         */
			        var voReturnVal = dialog.returnValue;
			        
			        if (!ValueUtil.isNull(voReturnVal)) {
			            var dsDetailInfo = app.lookup("dsDetailInfo");
			            
			            //리턴값 설정
			            dsDetailInfo.setValue(0, "TRPR_INFO_NO", voReturnVal["TRPR_INFO_NO"]); //대상자번호
			            dsDetailInfo.setValue(0, "INDV_IDNTFC_NO", voReturnVal["INDV_IDNTFC_NO"]); //개인식별번호
			            dsDetailInfo.setValue(0, "TRPR_NM_ENCPT", voReturnVal["TRPR_NM"]); //성명
			            dsDetailInfo.setValue(0, "TRPR_BRTH_YMD", voReturnVal["TRPR_BRTH_YMD"]); //생년월일
			            if(voReturnVal["ZIP"] != null && voReturnVal["ZIP"] != '')
			                dsDetailInfo.setValue(0, "ZIP", voReturnVal["ZIP"]); //우편번호
			            if(voReturnVal["PST_ADDR"] != null && voReturnVal["PST_ADDR"] != '')
			                dsDetailInfo.setValue(0, "PST_ADDR", voReturnVal["PST_ADDR"]); //우편주소
			            if(voReturnVal["DADDR"] != null && voReturnVal["DADDR"] != '')
			                dsDetailInfo.setValue(0, "DADDR", voReturnVal["DADDR"]); //상세주소
			            dsDetailInfo.setValue(0, "RCPT_INST_NO", voReturnVal["RCPT_INST_NO"]); //접수기관번호
			            dsDetailInfo.setValue(0, "TRPR_TELNO", voReturnVal["TRPR_TELNO"]); //접수기관번호
			            
			            
			            util.Control.redraw(app, "grpData");
			        }
			        
			        if (dsDetailInfo.getValue(0, "TRPR_INFO_NO") != null) {
			            
			            doCreateList();
			        }
			    }, {
			        CHK_CD: "6"
			        , TRPR_NM: app.lookup("sipb6").value
			        , CRTF_CODE: "Y"
			    });
			    
